const terminalizeProcurementAgentRunStatus = `-- name: TerminalizeProcurementAgentRunStatus :execrows
UPDATE procurement_agent_runs
SET status = $1,
    failure_reason = $2,
    result_revision_id = COALESCE($3, result_revision_id),
    completed_at = now(),
    version = version + 1, updated_at = now()
WHERE id = $4
  AND status NOT IN ('SUCCEEDED','FAILED','CANCELLED','RESUMED','EXPIRED')
  AND $1 IN ('SUCCEEDED','FAILED','CANCELLED','RESUMED','EXPIRED')
`

type TerminalizeProcurementAgentRunStatusParams struct {
	Status           string `db:"status" json:"status"`
	FailureReason    string `db:"failure_reason" json:"failure_reason"`
	ResultRevisionID *int64 `db:"result_revision_id" json:"result_revision_id"`
	ID               int64  `db:"id" json:"id"`
}

// terminalize 專用的終態轉移：守衛只有 `id` ＋「現在還不是終態」，**刻意不比對
// version**（2026-09-07 決策：terminalize 不對 version 做 CAS，改用狀態機 guard）。
//
// 為什麼不共用下面那支：worker 宣告自己的執行結果**不是** read-modify-write——它
// 沒讀過快照、也不基於快照改值，它在陳述一件已經發生的事實。optimistic CAS on
// version 是給 cancel／resume 這種「拿著一份快照要改它」的呼叫端用的。兩者共用同
// 一支帶 version 述詞的 query 會讓 cancel（或 retry）bump 過版本之後，終態整個寫
// 不進去、而且無聲：TerminalizeRun 回 wrote=false 不是錯誤，呼叫端只記一行 Warn，
// 該 run 於是**永遠沒有終態 ledger event**，串流消費端等不到收線訊號，連線開到
// gateway 的 120 秒 deadline。
//
// 真正要防的是「不要覆寫一個已經終態的 run」，而那個守衛本來就在 WHERE 裡、不依賴
// version。started_at 不在這裡處理：terminalize 不會把 run 轉成 RUNNING。
func (q *Queries) TerminalizeProcurementAgentRunStatus(ctx context.Context, arg TerminalizeProcurementAgentRunStatusParams) (int64, error) {
	result, err := q.db.Exec(ctx, terminalizeProcurementAgentRunStatus,
		arg.Status,
		arg.FailureReason,
		arg.ResultRevisionID,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updateProcurementAgentRunStatus = `-- name: UpdateProcurementAgentRunStatus :execrows
UPDATE procurement_agent_runs
SET status = $1,
    failure_reason = $2,
    result_revision_id = COALESCE($3, result_revision_id),
    started_at = COALESCE(started_at, CASE WHEN $1 = 'RUNNING' THEN now() END),
    completed_at = CASE WHEN $1 IN ('SUCCEEDED','FAILED','CANCELLED','RESUMED','EXPIRED')
                        THEN now() ELSE completed_at END,
    version = version + 1, updated_at = now()
WHERE id = $4 AND version = $5
  AND status NOT IN ('SUCCEEDED','FAILED','CANCELLED','RESUMED','EXPIRED')
`

type UpdateProcurementAgentRunStatusParams struct {
	Status           string `db:"status" json:"status"`
	FailureReason    string `db:"failure_reason" json:"failure_reason"`
	ResultRevisionID *int64 `db:"result_revision_id" json:"result_revision_id"`
	ID               int64  `db:"id" json:"id"`
	Version          int64  `db:"version" json:"version"`
}

// version 是 v1 唯一的 CAS 欄位（doc57 §6.2 v1 不含 lease/fencing）。呼叫端帶
// 目前讀到的 version，UPDATE 命中才代表沒有被別的呼叫搶先轉移狀態。
//
// result_revision_id 用 COALESCE 保留原值：這支 query 服務三種轉移
// （terminalize／cancel／resume），只有 terminalize 帶得出真正的結果
// revision，另外兩種不該碰它。傳 NULL 代表「這次轉移不改動
// result_revision_id」，**不是**「把它清成 0」——後者會抹掉
// replayExistingRun 的就緒判準（answer.go/turn.go 的 `run.ResultRevisionID
// == 0` 判斷），也會讓 ledger 指向一個不存在的 revision id（Task 14b C1）。
func (q *Queries) UpdateProcurementAgentRunStatus(ctx context.Context, arg UpdateProcurementAgentRunStatusParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateProcurementAgentRunStatus,
		arg.Status,
		arg.FailureReason,
		arg.ResultRevisionID,
		arg.ID,
		arg.Version,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
